export const api = { 
  get: async (path) => { 
    const res = await fetch(path, { method: 'GET', credentials: 'include' }); 
    if (!res.ok) throw new Error('API error'); 
    return res.json(); 
  }, 
  post: async (path, body) => { 
    const res = await fetch(path, { 
      method: 'POST', 
      headers: { 'Content-Type': 'application/json' }, 
      credentials: 'include', 
      body: JSON.stringify(body), 
    }); 
    if (!res.ok) throw new Error('API error'); 
    return res.json(); 
  } 
};

export async function fetchMachineBySerial(serial) {
  const url = `/api/machines/?serial_number_machine=${encodeURIComponent(serial)}`;

  const res = await fetch(url, {
    credentials: 'include',
  });

  if (!res.ok) {
    return null;
  }

  const data = await res.json();

  if (Array.isArray(data)) {
    return data[0] ?? null;
  }
  return data;
}

// загружать машины текущего пользователя
export async function fetchMachinesForCurrentUser() {
  const url = '/api/machines/';
  const res = await fetch(url, {
    credentials: 'include',
  });
  if (!res.ok) {
    // можно вернуть пустой массив или null в зависимости от нужд
    return [];
  }
  const data = await res.json();
  // Если бекенд возвращает массив — возвращаем массив
  return Array.isArray(data) ? data : [data];
}
